s=importlib.util.spec_from_file_location('delivery',ROOT/'ops/apply-random-5000-round4-20261007.py');m=importlib.util.module_from_spec(s);s.loader.exec_module(m);r=m.r;RUN=m.RUN;d=m.d
def cell(v):return str(v or '').replace('|','\\|').replace('\n',' ')
def main():
 sample=r.load(RUN/'sample.json');rows=r.load(RUN/'baseline.json.gz');assert r.sha((RUN/'baseline.json.gz').read_bytes())==sample['baseline_sha256'];newids=sample['artwork_ids'];oldids=sample['followup_lead_ids'];assert len(newids)==5000 and len(oldids)==0 and not(set(newids)&set(oldids))
 previous=sum((r.load(folder/'sample.json')['artwork_ids'] for folder in [m.OLD,m.t.t.SECOND,m.t.t.PREV]),[]);assert len(set(previous))==15000 and not(set(newids)&set(previous))
 applied={};applied_wave={};verifications=[];deliveryholds=[];newinstitutions={}
