 assert task_assertions==len(applied)
 for aid,c in applied.items():assert live[aid]['artwork']['current_institution_id']==c['institution']['id']
 wd=r.load(RUN/'wikidata-assessment-v5.json.gz');wdby={x['artwork_id']:x for x in wd['outcomes']};wiki=r.load(RUN/'wikiart-holding-plan-v12.json.gz');wikiby={x['artwork_id']:x for x in wiki['outcomes']};native=r.load(RUN/'native-identity-preflight.json.gz');combined=r.load(RUN/'primary-plans/combined-80-reviewed.json.gz');held=collections.defaultdict(list)
 for h in [*native['held'],*deliveryholds,*combined['holds']]:held[h['artwork_id']].append(h)
 webpins=[];webleads=collections.defaultdict(list)
