 queried={q['artwork_id']for p in(RUN/'web-discovery').glob('*.json')for q in r.load(p)['queries']};assert len(queried)==4217 and queried<=set(newids+oldids);initial=r.load(RUN/'initial-source-review.json');assert set(newids)<=queried|set(initial['new_sample_exact_source_ids'])
 editorial=r.load(RUN/'additional-editorial-decisions.json');combinedby={c['artwork_id']:c for c in combined['claims']}
 ledgers={};concurrent=[]
 for name,ids in [('new-5000',newids)]:
  ledger=[]
